create or replace function public.nearby_locations_enriched(lat double precision,lng double precision,radius_meters integer default 16093,limit_count integer default 200,required_amenity_ids uuid[] default null) returns table(id uuid,name text,business_id uuid,address text,city text,state text,latitude double precision,longitude double precision,distance_meters double precision,rating numeric,review_count integer,cleanliness_pct numeric,accessible boolean,changing_table boolean,place_type text,amenities jsonb,fixtures jsonb) language sql stable security definer set search_path=public,extensions as $$ with candidates as (select l.*, round(extensions.st_distance(extensions.st_setsrid(extensions.st_makepoint(l.longitude,l.latitude),4326)::extensions.geography,extensions.st_setsrid(extensions.st_makepoint(lng,lat),4326)::extensions.geography)::numeric,1) distance_meters from public.locations l where l.is_active=true and l.latitude is not null and l.longitude is not null and extensions.st_dwithin(extensions.st_setsrid(extensions.st_makepoint(l.longitude,l.latitude),4326)::extensions.geography,extensions.st_setsrid(extensions.st_makepoint(lng,lat),4326)::extensions.geography,greatest(100,radius_meters))), filtered as (select c.* from candidates c where required_amenity_ids is null or cardinality(required_amenity_ids)=0 or (select count(distinct la.amenity_id) from public.location_amenities la where la.location_id=c.id and la.amenity_id=any(required_amenity_ids))=cardinality(required_amenity_ids)) select c.id,c.name,c.business_id,c.address,c.city,c.state,c.latitude,c.longitude,c.distance_meters,c.rating,c.review_count,c.cleanliness_pct,c.accessible,c.changing_table,c.place_type,coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'category',a.category) order by a.category,a.name) from public.location_amenities la join public.amenities a on a.id=la.amenity_id where la.location_id=c.id),'[]'::jsonb),coalesce((select jsonb_build_object('stalls',f.stalls,'urinals',f.urinals,'sinks',f.sinks,'hand_dryers',f.hand_dryers,'changing_tables',f.changing_tables,'showers',f.showers) from public.location_fixtures f where f.location_id=c.id),'{}'::jsonb) from filtered c order by c.distance_meters limit greatest(1,least(limit_count,200)); $$; grant execute on function public.nearby_locations_enriched(double precision,double precision,integer,integer,uuid[]) to authenticated;
